/// <summary>
/// Data contract for the @TaxTransactionInquiry:HeaderNote report.
/// Defines dialog parameters shown to the user before report execution.
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessing(classStr(ConDemoCustGroupReportUIBuilder))
]
public class ConDemoCustGroupReportContract
{
    str custGroup;

}

Method.Source:
/// <summary>
/// Gets or sets the custGroup parameter.
/// </summary>
/// <param name="_custGroup">The custGroup value.</param>
/// <returns>The current custGroup value.</returns>
[DataMemberAttribute('custGroup'),
    SysOperationLabelAttribute('@TaxTransactionInquiry:HeaderNote')]
    public str parmCustGroup(str _custGroup = custGroup)
{
    custGroup = _custGroup;
    return custGroup;
}
